import numpy as np
import matplotlib.pyplot as plt

# EXERCISE 2: NUMERICAL SOLUTION USING IMPLICIT TRAPEZOIDAL METHOD
 
# RESULTS ANALYSIS AND COMPARISON:
# 1. Convergence of the Numerical Solution:
#    As the step size h decreases (0.1 -> 0.01 -> 0.001), the numerical solution 
#    generated by the Implicit Trapezoidal Method rapidly converges towards 
#    the true analytical solution: y(t) = 2 - exp(-t^2 / 4).

# 2. Global Error and Precision Order O(h^2):
#    The Implicit Trapezoidal Method has a local truncation error of O(h^3) 
#    and a global truncation error of O(h^2). For h = 0.001, the numerical curve 
#    is visually indistinguishable from the exact solution.

# 3. Unconditional Stability (A-Stability):
#    Because the Trapezoidal rule is an implicit method, it is A-stable, ensuring 
#    the numerical solution remains smooth and stable for all tested step sizes.

# 1. Define the ODE right-hand side function f(t, y) and exact solution
def f(t, y):
    return (t / 2.0) * (2.0 - y)

def y_exact(t):
    return 2.0 - np.exp(- (t**2) / 4.0)

# 2. Problem parameters
t0, t_final = 0.0, 4.0
y0 = 1.0
h_values = [0.1, 0.01, 0.001]

# 3. Create plot figure
plt.figure(figsize=(10, 6))

# Plot analytical exact solution
t_exact = np.linspace(t0, t_final, 1000)
plt.plot(t_exact, y_exact(t_exact), 'k-', linewidth=2, label=r'Exact Solution: $y(t) = 2 - e^{-t^2/4}$')

# 4. Loop over each step size h
colors = ['r--', 'g--', 'b:']
for h, color in zip(h_values, colors):
    N = int((t_final - t0) / h)
    t = np.linspace(t0, t_final, N + 1)
    y = np.zeros(N + 1)
    y[0] = y0
    
    # Implicit Trapezoidal loop (using algebraically solved y_{n+1})
    for n in range(N):
        tn = t[n]
        tn1 = t[n+1]
        yn = y[n]
        fn = f(tn, yn)
        
        # Explicit update formula derived from implicit Trapezoidal rule
        y[n+1] = (yn + (h / 2.0) * fn + (h * tn1) / 2.0) / (1.0 + (h * tn1) / 4.0)
        
    # Plot numerical result
    plt.plot(t, y, color, label=f'Trapezoidal (h = {h})')

# 5. Graph formatting
plt.title('Comparison of Implicit Trapezoidal Method for Different Step Sizes $h$', fontsize=12)
plt.xlabel('Time ($t$)', fontsize=11)
plt.ylabel('$y(t)$', fontsize=11)
plt.grid(True, linestyle='--', alpha=0.7)
plt.legend(fontsize=10)
plt.tight_layout()
plt.show()